import React, { useState, useEffect, useContext } from 'react';
import { AppContext } from '../context/AppContext';
import { useNavigate } from 'react-router-dom';

const OrdersPage = () => {
  const [orders, setOrders] = useState([]);
  const { fetchOrders, loading, user } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadOrders();
  }, [user]);

  const loadOrders = async () => {
    const data = await fetchOrders();
    setOrders(data);
  };

  const getStatusColor = (status) => {
    switch(status?.toLowerCase()) {
      case 'completed': return 'bg-green-100 text-green-800 border-green-200';
      case 'pending': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'shipped': return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'cancelled': return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  return (
    <div className="max-w-4xl mx-auto mt-8 px-4">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">My Orders</h1>
      {loading && <p className="text-center">Loading...</p>}
      {orders.length === 0 ? (
        <p className="text-center text-xl text-gray-600 py-8">No orders yet</p>
      ) : (
        <div className="grid gap-4">
          {orders.map(order => {
            const orderDate = new Date(order.orderDate);
            const deliveryDate = new Date(orderDate.getTime() + 7 * 24 * 60 * 60 * 1000);

            return (
              <div key={order._id} className={`p-4 rounded-lg shadow-md border-2 hover:shadow-lg transition-shadow ${getStatusColor(order.status)}`}>
                <div className="flex gap-4">
                  <div className="flex-shrink-0">
                    <img src={order.bookId?.image || 'https://via.placeholder.com/100x130?text=Book'} alt={order.bookId?.title} className="w-20 h-26 object-cover rounded-lg shadow-sm" />
                  </div>
                  <div className="flex-grow">
                    <h3 className="text-lg font-bold mb-2">{order.bookId?.title}</h3>
                    <p className="text-sm mb-1"><span className="font-semibold">Author:</span> {order.bookId?.author}</p>
                    <p className="text-sm mb-1"><span className="font-semibold">Quantity:</span> {order.quantity} books</p>
                    <p className="text-sm mb-1"><span className="font-semibold">Price:</span> ₹{order.bookId?.price} each</p>
                    <p className="font-bold text-lg mb-2">Total: ₹{order.totalAmount}</p>

                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <p className="mb-1"><span className="font-semibold">Order Date:</span> {orderDate.toLocaleDateString()}</p>
                        <p className="mb-1"><span className="font-semibold">Delivery Date:</span> {deliveryDate.toLocaleDateString()}</p>
                      </div>
                      <div>
                        <p className="mb-1"><span className="font-semibold">Status:</span> <span className="capitalize font-semibold">{order.status}</span></p>
                        <p className="text-xs">Delivered to: {order.shippingAddress?.city}</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default OrdersPage;
